record.field:
# ICC PRO OAuth2 Password Grant Authentication
remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}

username = (cfg.get('username') or '').strip()
password = (cfg.get('password') or '').strip()
client_id = (cfg.get('client_id') or '').strip()
client_secret = (cfg.get('client_secret') or '').strip()

if not username or not password:
    raise Exception("Missing ICC PRO credentials: set username/password in connection_params.")
if not client_id or not client_secret:
    raise Exception("Missing OAuth2 client credentials: set client_id/client_secret in connection_params.")

# Build token URL
url = (base_url or '').rstrip('/') + '/token'

# OAuth2 Password Grant requires form-urlencoded data
token_data = {
    'grant_type': 'password',
    'username': username,
    'password': password,
    'client_id': client_id,
    'client_secret': client_secret
}

headers = {
    'Content-Type': 'application/x-www-form-urlencoded'
}

resp = request_retry('POST', url, data=token_data, headers=headers, timeout=timeout)

if resp.status_code >= 400:
    raise Exception("Token request failed: %s %s" % (resp.status_code, resp.text))

try:
    token_response = resp.json()
except Exception as e:
    raise Exception("Failed to parse token response: %s" % str(e))

access_token = token_response.get('access_token')
if not access_token:
    raise Exception("Token response missing access_token: %s" % str(token_response))

# Store token info in bag
bag['access_token'] = access_token
bag['token_type'] = token_response.get('token_type', 'bearer')
bag['expires_in'] = token_response.get('expires_in')

result = 'Token obtained successfully. Type: %s, Expires in: %s seconds' % (
    bag['token_type'],
    bag['expires_in']
)

# Build sensor plan from device/sensor remotecontrol_params
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()

# Get all sensors with remotecontrol_params configured for THIS remote control
condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
    ('active', '=', True),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)

# Build map of sensor_id -> most recent reading (single query optimization)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]

# Build execution plan
sensor_plan = []

for sensor in sensors:
    device = sensor.device_id

    # Parse sensor configuration
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}

    # Parse device configuration
    try:
        device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        device_cfg = {}

    # Get meter_id from sensor or device config
    meter_id = sensor_cfg.get('meter_id') or device_cfg.get('meter_id')
    value_field = sensor_cfg.get('value_field', 'AccVolume')  # Default to totalizer

    if not meter_id:
        continue

    # Determine initial date for this sensor
    last_reading_time = last_readings_map.get(sensor.id)
    if last_reading_time:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_reading_time))
        except Exception:
            initial_date = str(last_reading_time)[:10]
    else:
        # Use start_date from sensor config or device config, or Jan 1 of current year
        start_cfg = sensor_cfg.get('start_date') or device_cfg.get('start_date')
        if start_cfg:
            initial_date = start_cfg[:10]
        else:
            year_str = today_str[:4]
            initial_date = '%s-01-01' % year_str

    plan_item = {
        'odoo_sensor_id': sensor.id,
        'odoo_device_id': device.id,
        'meter_id': meter_id,
        'value_field': value_field,
        'start_date': initial_date
    }
    sensor_plan.append(plan_item)

bag['sensor_plan'] = sensor_plan
bag['plan_count'] = len(sensor_plan)

result = 'Built sensor plan with %d sensors' % len(sensor_plan)

# Get readings from ICC PRO and upsert into Odoo
if 'access_token' not in bag:
    raise Exception('Please run "ICC PRO: Get Token" action first')
if 'sensor_plan' not in bag:
    raise Exception('Please run "ICC PRO: Build Sensor Plan" action first')

Remote = self.remote_id
access_token = bag['access_token']
sensor_plan = bag['sensor_plan']

auth_headers = {
    'Authorization': 'Bearer %s' % access_token,
    'Content-Type': 'application/x-www-form-urlencoded'
}

Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()
# Format dates for ICC PRO API: YYYYMMDDHHmmss
today_api = today_str.replace('-', '') + '235959'

# Determine earliest start_date from all sensors
earliest_date = None
for plan_item in sensor_plan:
    start_date = plan_item['start_date']
    if earliest_date is None or start_date < earliest_date:
        earliest_date = start_date

if earliest_date is None:
    earliest_date = today_str[:4] + '-01-01'  # Default to Jan 1st of current year

start_date_api = earliest_date.replace('-', '') + '000000'

# Single API call to get ALL meters readings
url_readings = (base_url or '').rstrip('/') + '/api/accumulation/meters'
params = {
    'utc': 'true',
    'fromdatetime': start_date_api,
    'todatetime': today_api,
    'resolution': '2'  # Daily resolution
    # NO mid parameter = returns all meters
}

try:
    resp = request_retry('GET', url_readings, headers=auth_headers, params=params, timeout=timeout)

    if resp.status_code == 401:
        raise Exception("Authentication failed: Token may be expired")

    if resp.status_code >= 400:
        raise Exception("HTTP %d: %s" % (resp.status_code, resp.text[:200]))

    response_data = resp.json() or {}
    data_list = response_data.get('Data', [])

except Exception as e:
    raise Exception("Failed to get readings from ICC PRO: %s" % str(e))

# Now process readings for each sensor
total_upserts = 0
total_errors = 0
items = []

for plan_item in sensor_plan:
    odoo_sensor_id = plan_item['odoo_sensor_id']
    meter_id = plan_item['meter_id']
    value_field = plan_item.get('value_field', 'AccVolume')

    sensor = Sensor.browse(odoo_sensor_id)
    if not sensor.exists():
        continue

    sensor_upserts = 0
    sensor_errors = 0
    readings_summary = []

    try:
        for data_point in data_list:
            try:
                # Time format: YYYYMMDDHHmmss
                time_str = data_point.get('Time', '')
                meters_data = data_point.get('MetersData', [])

                if not time_str or not meters_data:
                    continue

                # Parse timestamp: 20260101230000 -> 2026-01-01 23:00:00
                if len(time_str) >= 14:
                    timestamp = '%s-%s-%s %s:%s:%s' % (
                        time_str[0:4],   # year
                        time_str[4:6],   # month
                        time_str[6:8],   # day
                        time_str[8:10],  # hour
                        time_str[10:12], # minute
                        time_str[12:14]  # second
                    )
                else:
                    continue

                # Find meter data for our meter_id
                for meter_data in meters_data:
                    if meter_data.get('Id') == meter_id:
                        # Get value based on value_field (AccVolume or Volume)
                        value = meter_data.get(value_field, 0.0)
                        if value is None:
                            value = 0.0

                        # Upsert reading into Odoo
                        Remote.upsert(
                            'mdm.measurement.device.sensor.reading',
                            {
                                'sensor_id': odoo_sensor_id,
                                'measurement_time': timestamp
                            },
                            {
                                'value': float(value),
                                'remotecontrol_origin_id': Remote.id
                            }
                        )
                        sensor_upserts += 1

                        if len(readings_summary) < 5:
                            readings_summary.append({
                                'timestamp': timestamp,
                                'value': value,
                                'field': value_field
                            })
                        break

            except Exception as e:
                sensor_errors += 1
                if len(readings_summary) < 5:
                    readings_summary.append({
                        'error': str(e),
                        'raw': str(data_point)[:100]
                    })

        total_upserts += sensor_upserts
        total_errors += sensor_errors

        items.append({
            'sensor_id': odoo_sensor_id,
            'sensor_name': sensor.name,
            'meter_id': meter_id,
            'value_field': value_field,
            'status': 'success',
            'points_found': len(data_list),
            'upserts': sensor_upserts,
            'errors': sensor_errors,
            'sample_readings': readings_summary
        })

    except Exception as e:
        total_errors += 1
        items.append({
            'sensor_id': odoo_sensor_id,
            'sensor_name': sensor.name,
            'meter_id': meter_id,
            'status': 'error',
            'error': str(e)
        })

# Create audit attachment
audit = {
    'executed_at': str(fields.Datetime.now()),
    'end_date': today_str,
    'total_upserts': total_upserts,
    'total_errors': total_errors,
    'sensors_processed': len(sensor_plan),
    'items': items
}

try:
    audit_json = json.dumps(audit, ensure_ascii=True, indent=2, default=str)
    b64 = base64.b64encode(audit_json.encode('utf-8'))
except Exception as json_error:
    simple_audit = {
        'executed_at': str(fields.Datetime.now()),
        'total_upserts': total_upserts,
        'total_errors': total_errors,
        'error': str(json_error)
    }
    audit_json = json.dumps(simple_audit, ensure_ascii=True, indent=2)
    b64 = base64.b64encode(audit_json.encode('utf-8'))

fname = 'icc_pro_readings_%s.json' % (
    fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
)

att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': Remote.id
})

Remote.message_post(
    body=u"[ICC PRO Readings] upserts=%s errors=%s sensors=%s" % (
        total_upserts, total_errors, len(sensor_plan)
    ),
    attachment_ids=[att.id]
)

bag['upserts'] = total_upserts
bag['errors'] = total_errors
bag['audit_attachment_id'] = att.id

result = 'Processed %d sensors, %d readings upserted, %d errors' % (len(sensor_plan), total_upserts, total_errors)

# Get last readings from ICC PRO for all configured meters
# Returns nested dictionary: {meter_id: {date: ..., value: ...}}
if 'access_token' not in bag:
    raise Exception('Please run "ICC PRO: Get Token" action first')

Remote = self.remote_id
access_token = bag['access_token']

auth_headers = {
    'Authorization': 'Bearer %s' % access_token,
    'Content-Type': 'application/x-www-form-urlencoded'
}

# Get current time and last 3 hours window
from datetime import datetime, timedelta
now_dt = datetime.now()
from_dt = now_dt - timedelta(hours=3)
from_datetime_api = from_dt.strftime('%Y%m%d%H%M%S')
to_datetime_api = now_dt.strftime('%Y%m%d%H%M%S')

# Single API call to get ALL meters readings (no mid parameter)
url_readings = (base_url or '').rstrip('/') + '/api/accumulation/meters'
params = {
    'utc': 'true',
    'fromdatetime': from_datetime_api,
    'todatetime': to_datetime_api,
    'resolution': '2'
    # NO mid parameter = returns all meters
}

try:
    resp = request_retry('GET', url_readings, headers=auth_headers, params=params, timeout=timeout)

    if resp.status_code == 401:
        raise Exception("Authentication failed: Token may be expired")

    if resp.status_code >= 400:
        raise Exception("HTTP %d: %s" % (resp.status_code, resp.text[:200]))

    response_data = resp.json() or {}
    data_list = response_data.get('Data', [])

except Exception as e:
    raise Exception("Failed to get readings from ICC PRO: %s" % str(e))

# Process all meters from the response
last_readings = {}
total_readings = 0

if data_list:
    # Get the last data point (most recent timestamp)
    last_point = data_list[-1]
    time_str = last_point.get('Time', '')
    meters_data = last_point.get('MetersData', [])

    # Parse timestamp once
    if len(time_str) >= 14:
        timestamp = '%s-%s-%s %s:%s:%s' % (
            time_str[0:4], time_str[4:6], time_str[6:8],
            time_str[8:10], time_str[10:12], time_str[12:14]
        )
    else:
        timestamp = time_str

    # Build dictionary with all meters
    for meter_data in meters_data:
        meter_id = meter_data.get('Id')
        if meter_id:
            last_readings[meter_id] = {
                'date': timestamp,
                'value':float(meter_data.get('AccVolume', 0.0))/1000.0,
                'volume': meter_data.get('Volume', 0.0)
            }
            total_readings += 1

bag['last_readings'] = last_readings
bag['total_last_readings'] = total_readings

result = 'Retrieved last readings for %d meters' % total_readings
